# Retirement and legacy-fleet links for storage (three parts) and trade.
# GENERATED rather than hand-listed: the four families have identical structure,
# and a pair of hand-aligned 54-element vectors is precisely how the previous
# alignment breaks happened. `RetiredStockCum` is gone -- the legacy fleet is now
# a recursive balance (`eqXStockCap`) with no cumulative variable.
.ret_links <- function(pfx, cap_eq, cost_eq) {
  rs <- paste0("v", pfx, "RetiredStock")
  rn <- paste0("v", pfx, "RetiredNewCap")
  sc <- paste0("v", pfx, "StockCap")
  eq <- function(x) paste0("eq", pfx, x)
  data.frame(
    equation = c(eq("StockCap"), eq("StockCap"),
                 eq("RetiredNewCap"), eq("RetiredNewCap"),
                 eq("RetLo"), eq("RetLo"), eq("RetUp"), eq("RetUp"),
                 cap_eq, cap_eq, cost_eq, cost_eq),
    variable = c(sc, rs,
                 rn, paste0("v", pfx, "NewCap"),
                 rs, rn, rs, rn,
                 sc, rn, rs, rn),
    stringsAsFactors = FALSE)
}
.equation_variable <- rbind(
  .equation_variable,
  .ret_links("StorageOut", "eqStorageOutCap", "eqStorageRetCost"),
  .ret_links("StorageInp", "eqStorageInpCap", "eqStorageRetCost"),
  .ret_links("StorageStg", "eqStorageStgCap", "eqStorageRetCost"),
  .ret_links("Trade",      "eqTradeCap",      "eqTradeRetCost"),
  data.frame(
    equation = c("eqStorageRetCost", "eqTradeRetCost",
                 "eqStorageStockPhaseOut", "eqStorageStockPhaseOut",
                 "eqStoragePhaseOut"),
    variable = c("vStorageRetCost", "vTradeRetCost",
                 "vStorageStockPhaseOut", "vStorageOutStockCap",
                 "vStorageOutStockCap"),
    stringsAsFactors = FALSE))

# End-of-life aux links.
.equation_variable <- rbind(.equation_variable, data.frame(
  equation = c("eqTechPhaseOut", "eqTechPhaseOut", "eqTechPhaseOut", "eqTechPhaseOut", "eqTechPhaseOut", "eqStoragePhaseOut", "eqStoragePhaseOut", "eqStoragePhaseOut", "eqStoragePhaseOut", "eqStoragePhaseOut", "eqTechAInp", "eqTechAOut", "eqStorageAInp", "eqStorageAOut"),
  variable = c("vTechPhaseOut", "vTechCap", "vTechNewCap", "vTechRetiredStock", "vTechRetiredNewCap", "vStoragePhaseOut", "vStorageOutCap", "vStorageOutNewCap", "vStorageOutRetiredStock", "vStorageOutRetiredNewCap", "vTechPhaseOut", "vTechPhaseOut", "vStoragePhaseOut", "vStoragePhaseOut"),
  stringsAsFactors = FALSE))
# Legacy-fleet balance links.
.equation_variable <- rbind(.equation_variable, data.frame(
  equation = c("eqTechStockCap", "eqTechStockCap", "eqTechStockPhaseOut", "eqTechStockPhaseOut", "eqTechCap", "eqTechPhaseOut"),
  variable = c("vTechStockCap", "vTechRetiredStock", "vTechStockPhaseOut", "vTechStockCap", "vTechStockCap", "vTechStockCap"),
  stringsAsFactors = FALSE))
.equation_variable <- .equation_variable[!is.na(.equation_variable$equation), ]
model_structure <- rbind(
	data.frame(name = names(.set_description), description = .set_description, 
						 type = 'set', dim = gsub('(["]|[)].*|^[^(]*[(]|NULL)', '', .set_set), map = ''),
	data.frame(name = names(.parameter_description), description = .parameter_description,
						 type = 'parameter', dim = gsub('(["]|[)].*|^[^(]*[(]|NULL)', '', .parameter_set), map = ''),
	data.frame(name = names(.variable_description), description = .variable_description, 
						 type = 'variable', dim = gsub('(["]|[)].*|^[^(]*[(])', '', .variable_set), 
	    map = gsub('[,]', ', ', gsub('(.*[$]|[ ])', '', sapply(.variable_mapping, 
			function(x) if (any(grep('[$]', x))) x else '')))))
